package cn.aiworkspace.personal;
import org.json.*;
import java.net.*;
import java.util.*;

/** Provider wire formats; independent of Android, exercised by the JVM HTTP tests. */
public final class ApiProtocol {
 public static final String[] TYPES={"chat","responses","claude","gemini"};
 public static final String[] LABELS={"OpenAI 兼容 Chat","OpenAI Responses","Claude Messages","Gemini 原生"};
 public static String normalizeBase(String value){
  try{String s=value.trim();while(s.endsWith("/"))s=s.substring(0,s.length()-1);URI u=new URI(s);
   J.require("https".equals(u.getScheme())&&u.getHost()!=null&&u.getUserInfo()==null&&u.getRawQuery()==null&&u.getFragment()==null,"API 地址需为完整 HTTPS 地址，不带密钥、查询参数或片段");
   String path=u.getPath();for(String suffix:new String[]{"/chat/completions","/responses","/messages","/models"})if(path.endsWith(suffix)){s=s.substring(0,s.length()-suffix.length());break;}
   J.require(!s.contains("{")&&!s.contains("}"),"请用控制台实际地址替换占位符");return s;
  }catch(URISyntaxException e){throw new IllegalArgumentException("API 地址格式无效");}
 }
 public static JSONObject validate(JSONObject value){JSONObject p=J.copy(value);String type=J.str(p,"protocol");J.require(Arrays.asList(TYPES).contains(type),"请选择接口协议");J.require(!J.str(p,"name").trim().isEmpty(),"请填写服务商名称");
  try{p.put("baseUrl",normalizeBase(J.str(p,"baseUrl")));int max=p.optInt("maxTokens",4096),timeout=p.optInt("timeout",180);J.require(max>=128&&max<=400000,"输出上限需为128—400000 token");J.require(timeout>=30&&timeout<=900,"超时需为30—900秒");int context=p.optInt("contextChars",160000);J.require(context>=1000&&context<=4000000,"上下文字数上限需为1000—4000000字符");String extra=J.str(p,"extra").trim();JSONObject x=extra.isEmpty()?new JSONObject():new JSONObject(extra);for(String key:new String[]{"model","messages","input","contents","system","systemInstruction","stream","store","n","max_tokens","max_output_tokens","max_completion_tokens"})J.require(!x.has(key),"高级参数不能覆盖 "+key);p.put("extra",x.toString());String header=J.str(p,"authHeader");J.require(header.isEmpty()||header.matches("[A-Za-z0-9-]{1,64}"),"鉴权Header名称无效");}catch(JSONException e){throw new IllegalArgumentException("高级参数必须是 JSON 对象");}return p;
 }
 public static String endpoint(JSONObject p,String model,boolean catalog){String base=J.str(p,"baseUrl"),kind=J.str(p,"protocol");if(catalog)return base+"/models"+(kind.equals("gemini")?"?pageSize=100":"");if(kind.equals("responses"))return base+"/responses";if(kind.equals("claude"))return base+"/messages";if(kind.equals("gemini")){J.require(model.matches("[A-Za-z0-9._/-]+"),"Gemini模型ID只能包含字母数字、点、下划线、斜线和连字符");if(model.startsWith("models/"))model=model.substring(7);J.require(!model.contains("..")&&!model.contains("/"),"请填写 Gemini 的短模型ID");return base+"/models/"+model+(p.optBoolean("stream",true)?":streamGenerateContent?alt=sse":":generateContent");}return base+"/chat/completions";}
 public static Map<String,String> headers(JSONObject p,String apiKey){Map<String,String> h=new LinkedHashMap<>();h.put("Content-Type","application/json");h.put("Accept",p.optBoolean("stream",true)?"text/event-stream":"application/json");String kind=J.str(p,"protocol"),custom=J.str(p,"authHeader");if(!custom.isEmpty())h.put(custom,custom.equalsIgnoreCase("Authorization")?"Bearer "+apiKey:apiKey);else if(kind.equals("claude"))h.put("x-api-key",apiKey);else if(kind.equals("gemini"))h.put("x-goog-api-key",apiKey);else h.put("Authorization","Bearer "+apiKey);if(kind.equals("claude"))h.put("anthropic-version","2023-06-01");return h;}
 public static JSONObject payload(JSONObject p,String model,String instructions,JSONArray history)throws JSONException{
  J.require(!model.trim().isEmpty(),"请先选择或填写模型ID");int chars=instructions.length();for(int i=0;i<history.length();i++)chars+=J.str(history.getJSONObject(i),"content").length();J.require(chars<=p.optInt("contextChars",160000),"当前上下文共"+chars+"字符，超过此服务商设置的上限。请新建对话或调整上限；内容没有被暗中删减。");
  String kind=J.str(p,"protocol");JSONObject o=J.obj("model",model);boolean stream=p.optBoolean("stream",true);int max=p.optInt("maxTokens",4096);
  if(kind.equals("gemini")){o.remove("model");JSONArray contents=new JSONArray();for(int i=0;i<history.length();i++){JSONObject m=history.getJSONObject(i);contents.put(J.obj("role",J.str(m,"role").equals("assistant")?"model":"user","parts",new JSONArray().put(J.obj("text",J.str(m,"content")))));}o.put("contents",contents);if(!instructions.isEmpty())o.put("systemInstruction",J.obj("parts",new JSONArray().put(J.obj("text",instructions))));o.put("generationConfig",J.obj("maxOutputTokens",max));}
  else if(kind.equals("responses")){o.put("input",history);if(!instructions.isEmpty())o.put("instructions",instructions);o.put("max_output_tokens",max);o.put("stream",stream);o.put("store",false);}
  else if(kind.equals("claude")){o.put("messages",history);if(!instructions.isEmpty())o.put("system",instructions);o.put("max_tokens",max);o.put("stream",stream);}
  else{JSONArray messages=new JSONArray();if(!instructions.isEmpty())messages.put(J.obj("role","system","content",instructions));for(int i=0;i<history.length();i++)messages.put(history.get(i));o.put("messages",messages);o.put(p.optBoolean("completionTokenField",false)?"max_completion_tokens":"max_tokens",max);o.put("stream",stream);}
  JSONObject extra=new JSONObject(p.optString("extra","{}"));Iterator<String> it=extra.keys();while(it.hasNext()){String k=it.next();if(kind.equals("gemini")&&k.equals("generationConfig")){JSONObject supplied=extra.getJSONObject(k),cfg=o.getJSONObject(k);Iterator<String> keys=supplied.keys();while(keys.hasNext()){String name=keys.next();if(!name.equals("maxOutputTokens"))cfg.put(name,supplied.get(name));}}else o.put(k,extra.get(k));}return o;
 }
 public static List<String> modelIds(JSONObject p,JSONObject response)throws JSONException{JSONArray a=response.optJSONArray(J.str(p,"protocol").equals("gemini")?"models":"data");J.require(a!=null,"此接口没有返回模型列表，可直接手动填写模型ID");TreeSet<String> names=new TreeSet<>();for(int i=0;i<a.length();i++){JSONObject m=a.optJSONObject(i);if(m==null)continue;String id=m.optString("id",m.optString("name",""));if(id.startsWith("models/"))id=id.substring(7);JSONArray methods=m.optJSONArray("supportedGenerationMethods");if(methods!=null&&!methods.toString().contains("generateContent"))continue;if(!id.isEmpty())names.add(id);}return new ArrayList<>(names);}

 public static final class Output {
  public final StringBuffer text=new StringBuffer();public JSONObject usage=new JSONObject();public String finish="",responseId="";public boolean terminal=false;
  public synchronized void event(String protocol,String event,String data)throws Exception{if(data.equals("[DONE]")){terminal=true;return;}JSONObject o=new JSONObject(data);if(!o.isNull("error")||event.equals("error")){Object error=o.opt("error");throw new java.io.IOException("服务商错误："+(error instanceof JSONObject?((JSONObject)error).optString("message",error.toString()):String.valueOf(error==null?data:error)));}if(o.has("id"))responseId=J.str(o,"id");if(o.optJSONObject("usage")!=null)mergeUsage(o.getJSONObject("usage"));
   if(protocol.equals("responses")){String type=o.optString("type",event);if(type.equals("response.output_text.delta")||type.equals("response.refusal.delta"))text.append(o.optString("delta",""));if(type.equals("response.completed")||type.equals("response.incomplete")||type.equals("response.failed")){JSONObject r=o.optJSONObject("response");if(r!=null){responseId=r.optString("id",responseId);if(r.optJSONObject("usage")!=null)mergeUsage(r.getJSONObject("usage"));if(text.length()==0)responseText(r);if(type.equals("response.failed"))throw new java.io.IOException("服务商返回失败："+J.pretty(r.opt("error")));}finish=type.equals("response.completed")?"stop":"incomplete";terminal=true;}}
   else if(protocol.equals("claude")){String type=o.optString("type",event);JSONObject m=o.optJSONObject("message");if(type.equals("message_start")&&m!=null){responseId=m.optString("id",responseId);if(m.optJSONObject("usage")!=null)mergeUsage(m.getJSONObject("usage"));}JSONObject d=o.optJSONObject("delta");if(type.equals("content_block_delta")&&d!=null&&d.optString("type").equals("text_delta"))text.append(d.optString("text",""));if(type.equals("message_delta")&&d!=null)finish=d.optString("stop_reason",finish);if(type.equals("message_stop"))terminal=true;}
   else if(protocol.equals("gemini")){JSONArray a=o.optJSONArray("candidates");if(o.optJSONObject("usageMetadata")!=null)mergeUsage(o.getJSONObject("usageMetadata"));if(a!=null&&a.length()>0){JSONObject c=a.getJSONObject(0);JSONObject content=c.optJSONObject("content");if(content!=null)parts(content.optJSONArray("parts"),false);if(c.has("finishReason")){finish=c.optString("finishReason");terminal=true;}}else if(o.has("promptFeedback"))throw new java.io.IOException("服务商没有返回正文："+o.get("promptFeedback"));}
   else{JSONArray a=o.optJSONArray("choices");if(a!=null&&a.length()>0){JSONObject c=a.getJSONObject(0),d=c.optJSONObject("delta");if(d!=null)appendContent(d.opt("content"));if(!c.isNull("finish_reason")&&!J.str(c,"finish_reason").isEmpty()){finish=c.optString("finish_reason");terminal=true;}}}
  }
  public synchronized void full(String protocol,JSONObject o)throws Exception{if(!o.isNull("error"))throw new java.io.IOException("服务商错误："+o.get("error"));responseId=o.optString("id","");if(o.optJSONObject("usage")!=null)mergeUsage(o.getJSONObject("usage"));if(protocol.equals("responses")){responseText(o);String status=o.optString("status","completed");finish=status.equals("completed")?"stop":status;}
   else if(protocol.equals("claude")){parts(o.optJSONArray("content"),false);finish=o.optString("stop_reason","");}
   else if(protocol.equals("gemini")){event(protocol,"",o.toString());}
   else{JSONObject c=o.getJSONArray("choices").getJSONObject(0);appendContent(c.getJSONObject("message").opt("content"));finish=c.optString("finish_reason","");}terminal=true;}
  void responseText(JSONObject r)throws JSONException{JSONArray a=r.optJSONArray("output");for(int i=0;a!=null&&i<a.length();i++)parts(a.optJSONObject(i)==null?null:a.optJSONObject(i).optJSONArray("content"),true);}
  void parts(JSONArray a,boolean responses){for(int i=0;a!=null&&i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p==null||p.optBoolean("thought",false))continue;String type=p.optString("type","");if(type.equals("refusal"))text.append(p.optString("refusal",""));else if(!responses||type.equals("output_text"))text.append(p.optString("text",""));}}
  void appendContent(Object value){if(value instanceof String)text.append(value);else if(value instanceof JSONArray)parts((JSONArray)value,false);}
  void mergeUsage(JSONObject u)throws JSONException{Iterator<String> it=u.keys();while(it.hasNext()){String k=it.next();usage.put(k,u.get(k));}}
  public synchronized Output snapshot(){Output o=new Output();o.text.append(text.toString());o.usage=J.copy(usage);o.finish=finish;o.responseId=responseId;o.terminal=terminal;return o;}
  public synchronized boolean complete(){return terminal&&text.length()>0&&(finish.isEmpty()||Arrays.asList("stop","end_turn","stop_sequence","STOP").contains(finish));}
 }
}
